permission_denials.command:
python3 -c "
import json,sys
try:
    import yaml
except ImportError:
    print('no pyyaml'); sys.exit(0)
p='journals/2026-08-19-chaos-latency-injection.md'
t=open(p).read()
fm=t.split('---',2)[1]
d=yaml.safe_load(fm)
ev={e['id'] for e in d['evidence']}
bad=[]
for h in d['hypotheses']:
    for r in h['evidence_for']+h['evidence_against']:
        if r not in ev: bad.append((h['id'],r))
for lf in d.get('latent_findings',[]):
    for r in lf['evidence']:
        if r not in ev: bad.append(('latent',r))
print('unresolved refs:',bad)
print('root_cause H state:',[h['state'] for h in d['hypotheses'] if h['id']==d['root_cause']['hypothesis']])
from datetime import datetime
s=datetime.fromisoformat(str(d['investigation']['started']).replace('Z','+00:00'))
c=datetime.fromisoformat(str(d['investigation']['concluded']).replace('Z','+00:00'))
print('wall clock computed:',int((c-s).total_seconds()),'declared:',d['usage']['wall_clock_seconds'])
print('evidence count:',len(ev))
"
